{"content": "const asar = require('@electron/asar');
const fs = require('fs');
const crypto = require('crypto');
const path = require('path');

(async () => {
  const archive = 'D:/deepseek harness/resources/app.asar';
  const files = await asar.listPackage(archive);
  const pick = (re) => files.filter((f) => re.test(f));

  console.log('--- settings-general files ---');
  console.log(pick(/dsh\/node_modules\/@deepseek-ai\/dsh-client-ui-settings-general\//).join('\n'));
  console.log('--- settings-models files ---');
  console.log(pick(/dsh\/node_modules\/@deepseek-ai\/dsh-client-ui-settings-models\//).join('\n'));
  console.log('--- dsh core lib files ---');
  console.log(pick(/^dsh\/node_modules\/@deepseek-ai\/dsh\/lib\//).join('\n'));

  for (const pkg of ['dsh-client-ui-settings-general', 'dsh-client-ui-settings-models']) {
    const pjBuf = await asar.extractFile(archive, `dsh/node_modules/@deepseek-ai/${pkg}/package.json`);
    const meta = JSON.parse(pjBuf.toString('utf8'));
    const client = await asar.extractFile(archive, `dsh/node_modules/@deepseek-ai/${pkg}/lib/client.js`);
    const sha = crypto.createHash('sha256').update(client).digest('hex');
    console.log(`${pkg}: version=${meta.version}`);
    console.log(`${pkg}: client.js sha256=${sha} bytes=${client.length}`);
  }

  // Export a few core CLI sources for review
  const outDir = 'C:/Users/BossYu/Documents/deepseek-harness/default-workspace/asar-tools/extracted';
  fs.mkdirSync(outDir, { recursive: true });
  for (const rel of [
    'dsh/node_modules/@deepseek-ai/dsh/lib/bin.js',
    'dsh/node_modules/@deepseek-ai/dsh/lib/plugin-BGnVfe_D.js',
    'dsh/node_modules/@deepseek-ai/dsh/package.json'
  ]) {
    try {
      const buf = await asar.extractFile(archive, rel);
      const dest = path.join(outDir, rel.replace(/[\\/]/g, '__'));
      fs.writeFileSync(dest, buf);
      console.log('exported:', dest, buf.length, 'bytes');
    } catch (e) {
      console.log('skip:', rel, e.message);
    }
  }
})().catch((e) => { console.error(e); process.exit(1); });
