const fs = require('fs');
const crypto = require('crypto');
const path = require('path');

(async () => {
  const archive = 'D:/deepseek harness/resources/app.asar';
  const files = await asar.listPackage(archive);
  const sep = files.find((f) => f.includes('dsh-client-ui-settings-general')) || '';
  console.log('sample entry format:', JSON.stringify(sep));

  const pick = (re) => files.filter((f) => re.test(f));

