    const pjRel = pick(new RegExp(pkgPrefix.replace(/\\/g, '\\\\') + 'package\\.json$'))[0];
    const clientRel = pick(new RegExp(pkgPrefix.replace(/\\/g, '\\\\') + 'lib\\\\client\\.js$'))[0];
    if (!pjRel || !clientRel) {
      console.log(`${pkg}: NOT FOUND in archive (pj=${pjRel} client=${clientRel})`);
      continue;
    }
    const pjBuf = await asar.extractFile(archive, pjRel);
