{"content": "const asar = require('@electron/asar');
const fs = require('fs');
const crypto = require('crypto');
const path = require('path');

(async () => {
  const archive = 'D:/deepseek harness/resources/app.asar';
  const files = await asar.listPackage(archive);
  const pick = (re) => files.filter((f) => re.test(f));

  for (const pkg of ['dsh-client-ui-settings-general', 'dsh-client-ui-settings-models']) {
    const pjRel = pick(new RegExp(`${pkg}[\\\\/]package\\.json$`))[0];
    const clientRel = pick(new RegExp(`${pkg}[\\\\/]lib[\\\\/]client\\.js$`))[0];
    if (!pjRel || !clientRel) {
      console.log(`${pkg}: NOT FOUND (pj=${pjRel} client=${clientRel})`);
      continue;
    }
    const pjBuf = await asar.extractFile(archive, pjRel);
    const meta = JSON.parse(pjBuf.toString('utf8'));
    const client = await asar.extractFile(archive, clientRel);
    const sha = crypto.createHash('sha256').update(client).digest('hex');
    console.log(`${pkg}: version=${meta.version}`);
    console.log(`${pkg}: client.js sha256=${sha} bytes=${client.length}`);
    console.log(`${pkg}: paths = ${pjRel} | ${clientRel}`);
  }

  const outDir = 'C:/Users/BossYu/Documents/deepseek-harness/default-workspace/asar-tools/extracted';
  fs.mkdirSync(outDir, { recursive: true });
  const wants = [
    /@deepseek-ai[\\/]dsh[\\/]lib[\\/]bin\.js$/,
    /@deepseek-ai[\\/]dsh[\\/]lib[\\/]plugin-[^\\/]+\.js$/,
    /@deepseek-ai[\\/]dsh[\\/]package\.json$/
  ];
  for (const want of wants) {
    const rel = pick(want)[0];
    if (!rel) { console.log('skip export (not found):', want); continue; }
    const buf = await asar.extractFile(archive, rel);
    const dest = path.join(outDir, rel.replace(/[\\/]/g, '__'));
    fs.writeFileSync(dest, buf);
    console.log('exported:', dest, buf.length, 'bytes');
  }
})().catch((e) => { console.error(e); process.exit(1); });
