const ws = 'C:/Users/BossYu/Documents/deepseek-harness/default-workspace/alt-plugins';
fs.mkdirSync(ws, { recursive: true });

const targets = [
  { repo: 'yoke233/dsh-openai-codex-auth', npm: 'dsh-openai-codex-auth', tag: 'v0.3.1' },
  { repo: 'cute-baobao/dsh-usage-meter', npm: '@dsh-usage-meter/usage', tag: 'v0.3.0' }
];

for (const t of targets) {
  console.log(`\n=== ${t.repo} ===`);

  // 1. Is it published on npm?
  const regUrl = 'https://registry.npmjs.org/' + t.npm.replace('/', '%2F');
  try {
    const res = await fetch(regUrl);
    if (res.ok) {
      const meta = await res.json();
      const versions = Object.keys(meta.versions ?? {});
      console.log(`npm: PUBLISHED. latest=${meta['dist-tags']?.latest} versions=${versions.slice(-6).join(', ')}`);
    } else {
      console.log(`npm: NOT published (HTTP ${res.status})`);
    }
  } catch (e) {
    console.log(`npm: lookup error ${e.message}`);
  }

  // 2. Resolve a git ref and download the repo tarball
  let ref = null;
  try {
    const res = await fetch(`https://api.github.com/repos/${t.repo}/tags`, { headers: { 'User-Agent': 'dsh-agent' } });
    if (res.ok) {
      const names = (await res.json()).map((x) => x.name);
      console.log(`tags: ${names.join(', ') || '(none)'}`);
      if (names.includes(t.tag)) ref = `refs/tags/${t.tag}`;
    } else {
      console.log(`tags API: HTTP ${res.status}`);
    }
  } catch (e) {
    console.log(`tags API error: ${e.message}`);
  }
  if (!ref) {
    const res = await fetch(`https://api.github.com/repos/${t.repo}`, { headers: { 'User-Agent': 'dsh-agent' } });
    if (res.ok) {
      const m = await res.json();
      ref = `refs/heads/${m.default_branch}`;
      console.log(`fallback ref: ${ref}`);
    }
  }
  if (!ref) { console.log('no ref resolved; skipping download'); continue; }

  const tgz = path.join(ws, `${t.repo.split('/')[1]}.tar.gz`);
  const res = await fetch(`https://codeload.github.com/${t.repo}/tar.gz/${ref}`);
  if (!res.ok) { console.log(`download HTTP ${res.status}`); continue; }
  fs.writeFileSync(tgz, Buffer.from(await res.arrayBuffer()));
  console.log(`downloaded: ${tgz} (${fs.statSync(tgz).size} bytes) via ${ref}`);

  // 3. Extract and check build artifacts
  const outDir = path.join(ws, t.repo.split('/')[1]);
  fs.rmSync(outDir, { recursive: true, force: true });
  fs.mkdirSync(outDir, { recursive: true });
  execFileSync('tar.exe', ['-xzf', tgz, '-C', outDir]);
  const root = path.join(outDir, fs.readdirSync(outDir)[0]);
  const hasLib = fs.existsSync(path.join(root, 'lib'));
  const mainRel = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')).main;
  console.log(`repo root: ${path.basename(root)}`);
  console.log(`lib/ committed: ${hasLib}  main=${mainRel}  main exists: ${fs.existsSync(path.join(root, mainRel ?? ''))}`);
  if (hasLib) console.log(`lib entries: ${fs.readdirSync(path.join(root, 'lib')).slice(0, 8).join(', ')}`);
}
